+      text-transform: uppercase;
+      letter-spacing: 0.16em;
+      font-size: 0.78rem;
+      font-weight: 700;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 3vw, 3rem);
+      line-height: 1.1;
+    }
+
+    .subtitle {
+      margin: 12px 0 0;
+      color: var(--muted);
+      max-width: 58ch;
+      line-height: 1.6;
+    }
+
+    .faq {
+      padding: 10px;
+    }
+
+    .example {
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent), var(--panel-2);
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      margin: 14px;
+      overflow: hidden;
+    }
+
+    .question {
+      width: 100%;
+      appearance: none;
+      border: 0;
+      background: transparent;
+      color: var(--text);
+      text-align: left;
+      cursor: pointer;
+      padding: 22px 22px;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 18px;
+      font: inherit;
+      font-weight: 650;
+      font-size: 1.04rem;
+    }
+
+    .question:focus-visible {
+      outline: 2px solid var(--accent);
+      outline-offset: -2px;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 32px;
+      height: 32px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      background: rgba(138, 180, 255, 0.12);
+      color: var(--accent);
+      transition: transform 160ms ease, background 160ms ease;
+    }
+
+    .details {
+      padding: 0 22px 22px;
+      color: var(--muted);
+      line-height: 1.7;
+      display: none;
+    }
+
+    .example[data-open="true"] .details {
+      display: block;
+    }
+
+    .example[data-open="true"] .icon {
+      transform: rotate(45deg);
+      background: rgba(197, 140, 255, 0.14);
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      .hero {
+        padding: 24px 20px 16px;
+      }
+
+      .faq {
+        padding: 8px;
+      }
+
+      .example {
+        margin: 10px 6px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="faq-title">
+      <header class="hero">
+        <p class="eyebrow">FAQ</p>
+        <h1 id="faq-title">Everything cat lovers ask</h1>
+        <p class="subtitle">A compact guide to common cat questions, from why they purr to how they decide where to nap.</p>
+      </header>
+
+      <div class="faq">
+        <div class="example" data-open="false">
+          <button class="question" type="button" aria-expanded="false">
+            Why do cats purr?
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            <p>Cats purr to show contentment, but they also use it when they are anxious, hurt, or seeking comfort. It is one of their most versatile forms of communication.</p>
+          </div>
+        </div>
+
+        <div class="example" data-open="false">
+          <button class="question" type="button" aria-expanded="false">
+            Why do cats knead blankets?
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            <p>Kneading is a comforting behavior that starts in kittenhood. Adult cats often keep doing it when they feel safe, relaxed, or especially attached to their favorite spot.</p>
+          </div>
+        </div>
+
+        <div class="example" data-open="false">
+          <button class="question" type="button" aria-expanded="false">
+            How much sleep do cats need?
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            <p>Most cats sleep between 12 and 16 hours a day, and some sleep even more. Their bursty hunting instincts make short naps a natural part of the routine.</p>
+          </div>
+        </div>
+
+        <div class="example" data-open="false">
+          <button class="question" type="button" aria-expanded="false">
+            Why do cats stare at you?
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            <p>A cat stare can mean curiosity, affection, or simple observation. If the rest of their body is relaxed, it is often just their quiet way of keeping tabs on the household.</p>
+          </div>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll('.example').forEach((example) => {
+      const button = example.querySelector('.question');
+      const details = example.querySelector('.details');
+
+      button.addEventListener('click', () => {
+        const isOpen = example.dataset.open === 'true';
+        example.dataset.open = String(!isOpen);
+        button.setAttribute('aria-expanded', String(!isOpen));
+        details.hidden = isOpen;
+        button.querySelector('.icon').textContent = isOpen ? '+' : '−';
+      });
+
+      details.hidden = true;
+    });
+  </script>
+</body>
+</html>
*** End Patch
