      border-radius: calc(var(--radius) + 6px);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: 32px 32px 18px;
      border-bottom: 1px solid var(--border);
      background: linear-gradient(135deg, rgba(138, 180, 255, 0.08), rgba(197, 140, 255, 0.04));
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.16em;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 12px 0 0;
      color: var(--muted);
      max-width: 58ch;
      line-height: 1.6;
    }

    .faq {
      padding: 10px;
    }

    .example {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent), var(--panel-2);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      margin: 14px;
      overflow: hidden;
    }

    .question {
      width: 100%;
      appearance: none;
      border: 0;
      background: transparent;
      color: var(--text);
      text-align: left;
