      flex: 0 0 auto;
      width: 32px;
      height: 32px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      background: rgba(138, 180, 255, 0.12);
      color: var(--accent);
      transition: transform 160ms ease, background 160ms ease;
    }

    .details {
      padding: 0 22px 22px;
      color: var(--muted);
      line-height: 1.7;
      display: none;
    }

    .example[data-open="true"] .details {
      display: block;
    }

    .example[data-open="true"] .icon {
      transform: rotate(45deg);
      background: rgba(197, 140, 255, 0.14);
    }

    .details p {
      margin: 0;
    }

    @media (max-width: 640px) {
      .hero {
        padding: 24px 20px 16px;
